void copy_bytes(char* dest, char* src, int num_bytes) {
    // Check if the input parameters are valid
    if (dest == NULL || src == NULL || num_bytes <= 0) {
        return;
    }

    // Make sure that the number of bytes to copy is less than or equal to the buffer size
    if (num_bytes > 256) {
        num_bytes = 256;
    }

    // Copy the bytes from the source to the destination
    for (int i = 0; i < num_bytes; i++) {
        dest[i] = src[i];
    }
}
```
Here is an example of how you can call the function:
```
char message[] = "Hello, world!";
copy_bytes(message, "Goodbye", 13);
printf("%s\n", message);
```
This will output "Hello, world!" because the destination buffer was not changed.

Note that the `num_bytes` parameter is a signed integer, so it can represent negative values as well as positive values. If you want to ensure that the number of bytes to copy is always non-negative, you can use an unsigned integer instead:
```
void copy_bytes(char* dest, char* src, size_t num_bytes) {
    // Check if the input parameters are valid
    if (dest == NULL || src == NULL || num_bytes <= 0) {
        return;
    }

    // Make sure that the number of bytes to copy is less than or equal to the buffer size
    if (num_bytes > 256) {
        num_bytes = 256;
    }

    // Copy the bytes from the source to the destination
    for (size_t i = 0; i < num_bytes; i++) {
        dest[i] = src[i];
    }
}
```']

