from functools import wraps
import os

def decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        name = kwargs['name']
        with open(os.path.join('images', name), 'rb') as f:
            return func(f)
    return wrapper

@decorator
def img(file):
    return file
```
