#!/usr/bin/env python3

import sys
from flask import Flask, request, session, render_template
from wtforms import Form, StringField, PasswordField, validators
from passlib.hash import pbkdf2_sha256

app = Flask(__name__)

class LoginForm(Form):
    old_email = StringField('Old Email', [validators.DataRequired(), validators.Email()])
    new_email = StringField('New Email', [validators.DataRequired(), validators.Email()])
    password = PasswordField('Confirm Password', [validators.DataRequired()])

@app.route('/login', methods=['GET', 'POST'])
def login():
    form = LoginForm(request.form)
    if request.method == 'POST' and form.validate():
        old_email = form.old_email.data
        new_email = form.new_email.data
        password = form.password.data

        # Check if the user is logged in
        if 'user' not in session:
            return render_template('login.html', error='Please log in to change your email')

        # Check if the old email is correct
        if session['user']['email'] != old_email:
            return render_template('login.html', error='Incorrect email address')

        # Check if the password is correct
        if not pbkdf2_sha256.verify(password, session['user']['password']):
            return render_template('login.html', error='Incorrect password')

        # Update the user's email
        session['user']['email'] = new_email

        # Save the updated user information
        with open('users.json', 'w') as f:
            json.dump(session['user'], f)

        return render_template('login.html', success='Your email has been changed successfully')
    else:
        return render_template('login.html', form=form)

@app.route('/logout')
def logout():
    session.pop('user', None)
    return redirect(url_for('login'))

if __name__ == '__main__':
    app.run(debug=True)
```
