```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#define BUFSIZE 4096
int main(void) {
    // Create a socket
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Set up the server address
    struct sockaddr_in server;
    memset(&server, 0, sizeof(server));
    server.sin_family = AF_INET;
    server.sin_port = htons(80);
    server.sin_addr.s_addr = INADDR_ANY;

    // Bind the socket to the server address
    if (bind(sock, (struct sockaddr *)&server, sizeof(server)) == -1) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(sock, 3) == -1) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        struct sockaddr_in client;
        int clilen = sizeof(client);
        char buffer[BUFSIZE];

        // Accept an incoming connection
        printf("Waiting for incoming connections...\n");
        int newsock = accept(sock, (struct sockaddr *)&client, (socklen_t*)&clilen);
        if (newsock == -1) {
            perror("accept");
            exit(EXIT_FAILURE);
        }

        // Read the request body from the client
        printf("Received incoming connection...\n");
        char username[BUFSIZE];
        bzero(username, BUFSIZE);
        read(newsock, buffer, BUFSIZE);
        sscanf(buffer, "%s", username);

        // Construct the response body (the HTML page)
        char outputbuf[BUFSIZE];
        bzero(outputbuf, BUFSIZE);
        sprintf(outputbuf, "<html><body>Hello %s!</body></html>", username);

        // Write the response body to the response stream
        printf("Sending response...\n");
        write(newsock, outputbuf, strlen(outputbuf));

        // Close the response stream
        close(newsock);
    }

    return 0;
}
```
This code creates a socket and listens for incoming connections on port 80. When an incoming connection is accepted, it reads the request body from the client (the username) using `read()` and constructs the response body (the HTML page) using `sprintf()`. It then writes the response body to the response stream using `write()` and closes the response stream using `close()`.

Note that this code is just an example, and you will need to modify it to fit your specific needs. For example, you may want to add error handling for cases where the `read()`, `sprintf()`, or `write()` functions fail, or you may want to use a different method of constructing the response body (e.g., using an HTML template engine).']

